"""Pinned first-run model download, independent of application Release updates."""
import ctypes
import hashlib
import json
import os
from pathlib import Path
import re
import tempfile
import time
from urllib.parse import urlsplit
from urllib.request import Request, urlopen


def manifest_for(root):
    manifest = json.loads((Path(root) / "config/model-manifest.json").read_text(encoding="utf-8"))
    if manifest.get("format") != 1 or manifest.get("target") != "models/large-v3-turbo":
        raise ValueError("Unsupported model manifest/target")
    if not re.fullmatch(r"[A-Za-z0-9_-]+/[A-Za-z0-9_.-]+", manifest.get("source", "")):
        raise ValueError("Invalid model source")
    if not re.fullmatch(r"[a-f0-9]{40}", manifest.get("revision", "")):
        raise ValueError("Model must use a pinned commit revision")
    seen = set()
    for item in manifest["files"]:
        name = item["name"]
        if name not in {"model.bin", "config.json", "preprocessor_config.json", "tokenizer.json", "vocabulary.json"} or name in seen:
            raise ValueError("Unexpected or duplicate model file")
        if not re.fullmatch(r"[a-f0-9]{64}", item["sha256"]) or not isinstance(item["bytes"], int) or item["bytes"] <= 0:
            raise ValueError("Model file size/hash is not pinned")
        seen.add(name)
    if not {"model.bin", "config.json", "tokenizer.json", "vocabulary.json"} <= seen:
        raise ValueError("Incomplete model manifest")
    return manifest


def valid_file(path, item):
    if not path.is_file() or path.stat().st_size != item["bytes"]:
        return False
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest() == item["sha256"]


def ask_download(manifest, missing):
    from .tray_i18n import startup_language
    size = sum(item["bytes"] for item in missing) / 1024**3
    if startup_language() == "ru":
        message = (f"Модель large-v3-turbo отсутствует или не прошла проверку.\n\n"
                   f"Скачать {size:.2f} GiB с Hugging Face?\nВерсия закреплена, файлы будут проверены по SHA-256.\n"
                   "После загрузки распознавание работает локально без интернета.")
    else:
        message = (f"The large-v3-turbo model is missing or failed verification.\n\n"
                   f"Download {size:.2f} GiB from Hugging Face?\nThe revision is pinned and SHA-256 will be verified.\n"
                   "After downloading, speech recognition works locally without internet.")
    return ctypes.windll.user32.MessageBoxW(None, message, "EXPC-WLK", 0x24) == 6


def show_progress(completed, total):
    from . import system_tray
    from .tray_i18n import startup_language
    icon = system_tray._startup_icon
    if icon is not None:
        label = "Загрузка модели" if startup_language() == "ru" else "Downloading model"
        icon.title = f"EXPC-WLK — {label}: {completed * 100 // total}%"


def ensure_model(root, consent=None, progress=None, opener=urlopen):
    root = Path(root).resolve()
    manifest = manifest_for(root)
    target = root / manifest["target"]
    if target.resolve() != target or root not in target.resolve().parents:
        raise ValueError("Model target must remain inside portable root")
    missing = [item for item in manifest["files"] if not valid_file(target / item["name"], item)]
    if not missing:
        return target  # Verified installed model: no network or prompt.
    if not (consent or ask_download)(manifest, missing):
        raise RuntimeError("Model download cancelled / Загрузка модели отменена.")
    target.mkdir(parents=True, exist_ok=True)
    total = sum(item["bytes"] for item in missing)
    completed = 0
    progress = progress or show_progress
    for item in missing:
        url = f"https://huggingface.co/{manifest['source']}/resolve/{manifest['revision']}/{item['name']}?download=true"
        request = Request(url, headers={"User-Agent": "EXPC-WLK-model-download"})
        fd, temporary = tempfile.mkstemp(prefix="." + item["name"] + "-", suffix=".download", dir=target)
        try:
            digest = hashlib.sha256()
            received = 0
            last_progress = 0.0
            with os.fdopen(fd, "wb") as output, opener(request, timeout=30) as response:
                final = urlsplit(response.url)
                if final.scheme != "https" or not (final.hostname == "huggingface.co" or
                        (final.hostname or "").endswith((".huggingface.co", ".hf.co"))):
                    raise ValueError("Unexpected model download host")
                while chunk := response.read(1024**2):
                    received += len(chunk)
                    if received > item["bytes"]:
                        raise ValueError("Model download exceeds pinned size")
                    output.write(chunk)
                    digest.update(chunk)
                    now = time.monotonic()
                    if now - last_progress > 0.5:
                        progress(completed + received, total)
                        last_progress = now
                output.flush()
                os.fsync(output.fileno())
            if received != item["bytes"] or digest.hexdigest() != item["sha256"]:
                raise ValueError("Model SHA-256 verification failed: " + item["name"])
            os.replace(temporary, target / item["name"])
            completed += received
            progress(completed, total)
            print("MODEL_VERIFIED " + item["name"], flush=True)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    return target
